import type {
  Decision,
  DraftBundle,
  FactcheckResult,
  NormalizedIntake,
  RenderableDocument,
  ResearchResult,
  StoredDocument,
} from "./types.js";

function provenance(): string {
  return [
    "",
    "---",
    "_Generated by the Client Onboarding Research Engine. Every figure carries a source;",
    "drafts are human-approved before delivery._",
    "",
  ].join("\n");
}

function header(intake: NormalizedIntake, title: string, decision: Decision): string {
  return [
    `# ${intake.clientName} — ${title}`,
    "",
    `_Industry: ${intake.industry} · Status: ${decision.status} by ${decision.decidedBy}_`,
    "",
    "",
  ].join("\n");
}

export function renderDocuments(
  intake: NormalizedIntake,
  research: ResearchResult,
  drafts: DraftBundle,
  factcheck: FactcheckResult,
  decision: Decision,
): RenderableDocument[] {
  const sources =
    research.sources.length > 0
      ? research.sources.map((source) => `- ${source.label}: ${source.detail}`)
      : ["- No external sources; based on client-provided intake."];

  const report = [
    header(intake, "Onboarding Report", decision),
    drafts.report,
    "",
    "## Research basis",
    "",
    `**Context brief.** ${research.contextBrief}`,
    "",
    "### Workflow audit",
    "",
    research.findings.workflowAudit,
    "",
    "### Tech stack",
    "",
    research.findings.techStack,
    "",
    "### Strategy",
    "",
    research.findings.strategy,
    "",
    "## Sources",
    "",
    ...sources,
    "",
    "## Quality gate",
    "",
    `- Passed: ${factcheck.passed ? "yes" : "no"}`,
    `- Draft attempts: ${factcheck.attempts}`,
    `- Open issues: ${factcheck.issues.length}`,
    provenance(),
  ].join("\n");

  return [
    {
      kind: "client-avatar",
      filename: "CLIENT-AVATAR.md",
      content: `${header(intake, "Client Avatar", decision)}${drafts.avatar}${provenance()}`,
    },
    {
      kind: "tone-of-voice",
      filename: "TONE-OF-VOICE.md",
      content: `${header(intake, "Tone of Voice", decision)}${drafts.tone}${provenance()}`,
    },
    {
      kind: "onboarding-report",
      filename: "ONBOARDING-REPORT.md",
      content: report,
    },
  ];
}

export function renderThinIntakeNotice(intake: NormalizedIntake, gaps: string[]): string {
  return [
    `Thin intake from ${intake.clientName} (${intake.industry}).`,
    "",
    "Research did not run. Missing or thin fields:",
    ...gaps.map((gap) => `- ${gap}`),
    "",
    'Reply with { "action": "supplement", "supplements": { "<field>": "<text>" }, "decidedBy": "you" }',
    'or { "action": "proceed", "decidedBy": "you" } to continue anyway.',
  ].join("\n");
}

export function renderApprovalNotice(
  intake: NormalizedIntake,
  factcheck: FactcheckResult,
): string {
  const issues =
    factcheck.issues.length > 0
      ? factcheck.issues.map((issue) => `- [${issue.severity}] ${issue.code}: ${issue.message}`)
      : ["- none"];

  return [
    `Onboarding documents for ${intake.clientName} are ready for sign-off.`,
    "",
    `Quality gate: ${factcheck.passed ? "PASSED" : "FAILED"} after ${factcheck.attempts} draft attempt(s).`,
    "",
    "Issues:",
    ...issues,
    "",
    'Approve with { "action": "approve", "decidedBy": "you" } or reject with { "action": "reject" }.',
  ].join("\n");
}

export function renderDeliveredNotice(
  intake: NormalizedIntake,
  documents: StoredDocument[],
): string {
  return [
    `Onboarding delivered for ${intake.clientName}.`,
    "",
    ...documents.map((document) => `- ${document.kind}: ${document.path}`),
  ].join("\n");
}
